Sure! Here's a JavaScript function that switches the order of adjectives in a sentence:

```javascript
function switchAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];
  let currentAdjective;

  for (let i = 0; i < words.length; i++) {
    if (words[i] === "beautiful" || words[i] === "green") {
      currentAdjective = words[i];
    } else if (currentAdjective) {
      adjectives.push(currentAdjective);
      currentAdjective = null;
    }
  }

  if (currentAdjective) {
    adjectives.push(currentAdjective);
  }

  return adjectives.join(" ") + " " + words.filter(word => !adjectives.includes(word)).join(" ");
}

const sentence = "Beautiful green trees are in the park";
const result = switchAdjectives(sentence);
console.log(result); // Output: Green beautiful trees are in the park
```

