Here's a C++ program that generates the Fibonacci sequence using a recursive function:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, num3;

    cout << "Enter the first two integers: ";
    cin >> num1 >> num2;

    if (!cin || num1 < 0 || num2 < 0) {
        throw runtime_error("Invalid input. Please enter positive integers.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num3;

    if (!cin || num3 <= 0) {
        throw runtime_error("Invalid input. Please enter a positive integer.");
    }

    int sequence[num3];
    sequence[0] = num1;
    sequence[1] = num2;

    for (int i = 2; i < num3; i++) {
        sequence[i] = fibonacci(i, num1, num2);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < num3; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

