import Foundation
import spacy

let nlp = try! spacy.load("en_core_web_sm")

func correctHomophones(text: String) -> String {
    let doc = nlp(text)
    var correctedText = ""

    for token in doc:
        if token.is_punct or token.is_stop or token.is_digit {
            correctedText += token.text
            continue
        }

        let lemma = token.lemma_
        if lemma != token.text {
            correctedText += lemma
        } else {
            correctedText += token.text
        }
    }

    return correctedText
}

