Here's a simple After Effects script to create a vertical video by stacking two other videos and adding subtitles to the top half of the video. Make sure you have both videos and the text file in a folder on your desktop before running the script.

```javascript
function main() {
    // Set the path to your video and text files
    var videoFolder = Folder.desktop.child("VideoFolder");
    var videoFile1 = videoFolder.child("video1.mp4");
    var videoFile2 = videoFolder.child("video2.mp4");
    var textFile = videoFolder.child("subtitles.txt");

    // Create a new composition
    var comp = app.activeComposition;

    // Import the first video file
    var video1 = comp.layers.add(videoFile1);
    video1.name = "Video 1";

    // Import the second video file
    var video2 = comp.layers.add(videoFile2);
    video2.name = "Video 2";

    // Stack the videos vertically
    var stackedVideos = [video1, video2];
    for (var i = 1; i < stackedVideos.length; i++) {
        stackedVideos[i].transform.position.y = stackedVideos[i - 1].bounds.height;
    }

    // Add subtitles to the top half of the video
    var subtitleLayer = comp.layers.addText(textFile.contents, "Subtitles");
    subtitleLayer.name = "Subtitles";
    subtitleLayer.transform.position.y = video1.bounds.height / 2;

    // Set the subtitle layer's font and size
    subtitleLayer.font = "Arial";
    subtitleLayer.size = 24;

    // Render the composition
    comp.render();
}

main();
```

