Here's an example Google Apps Script that searches for a place name in a column and stores the latitude and longitude in other columns:
```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A2:A"); // Assuming your data starts in cell A2
  var placeName = dataRange.getValue();

  var geocoder = new google.maps.Geocoder();
  geocoder.geocode({ 'address': placeName }, function(results, status) {
    if (status == 'OK') {
      var latitude = results[0].geometry.location.lat();
      var longitude = results[0].geometry.location.lng();

      sheet.getRange("B2").setValue(latitude); // Assuming your latitude column starts in cell B2
      sheet.getRange("C2").setValue(longitude); // Assuming your longitude column starts in cell C2
    } else {
      sheet.getRange("B2").setValue("Error"); // Assuming your error column starts in cell B2
      sheet.getRange("C2").setValue("Error"); // Assuming your error column starts in cell C2
    }
  });
}
```
This script will search for the place name in the first cell of column A, and if it finds a match, it will store the latitude and longitude in the corresponding cells in columns B and C, respectively. If there is an error, it will store "Error" in those cells. You can modify the script to search for place names in other columns or to store the latitude and longitude in different columns as needed.

