function getOptionValues(dotNotationString, key) {
  const options = {};

  // Split the dot notation string into an array of keys
  const keys = dotNotationString.split(".");

  // Iterate through each key and retrieve the corresponding value from the object
  for (const key of keys) {
    if (!options[key]) {
      options[key] = [];
    }

    options[key] = options[key].concat(getOptionValues(options[key], key));
