Here's a Python script using NLTK library to identify the most common non-silent vowel and consonant combinations in a given text:

```python
import nltk
from nltk.corpus import stopwords
from nltk.tokenize import word_tokenize
from nltk.stem import WordNetLemmatizer

def get_non_silent_vowels():
    return ['a', 'e', 'i', 'o', 'u']

def get_non_silent_consonants():
    return 'bcdfghjklmnpqrstvwxyz'

def extract_vowel_consonant_combinations(text):
    tokens = word_tokenize(text)
    tokens = [token.lower() for token in tokens if token.isalpha()]
    tokens = [token for token in tokens if token not in stopwords.words('english')]
    lemmatizer = WordNetLemmatizer()
    tokens = [lemmatizer.lemmatize(token) for token in tokens]

    vowel_consonant_combinations = []
    for token in tokens:
        if token[0].lower() in get_non_silent_vowels():
            vowel_consonant_combinations.append((token[0], token[1:]))

    return vowel_consonant_combinations

def count_frequency(combinations):
    frequency = {}
    for combination in combinations:
        key = tuple(combination)
        if key in frequency:
            frequency[key] += 1
        else:
            frequency[key] = 1

    return frequency

def main(text):
    vowel_consonant_combinations = extract_vowel_consonant_combinations(text)
    frequency = count_frequency(vowel_consonant_combinations)

    print("Most common non-silent vowel and consonant combinations:")
    for combination, count in frequency.items():
        print(f"{combination}: {count}")

