def english_number_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    words = []
    if n < 0:
        words.append("negative")
        n *= -1

    divider = 100000000
    while n // divider > 0:
        words.append(str(n // divider))
        n -= n // divider * divider
