Here's a Go code that identifies if a given sentence contains a double negative using a table of specific negative words:

```go
package main

import (
	"fmt"
	"strings"
)

var negativeWords = []string{"not", "never", "no", "none", "nothing"}

func isDoubleNegative(sentence string) bool {
	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word) && containsNotFollowedByNegativeWord(word) {
			return true
		}
	}
	return false
}

func containsNegativeWord(word string) bool {
	for _, w := range negativeWords {
		if w == word {
			return true
		}
	}
	return false
}

func containsNotFollowedByNegativeWord(word string) bool {
	if word == "not" {
		return false
	}
	prevWord := words[len(words)-2]
	if prevWord == "not" && containsNegativeWord(word) {
		return true
	}
	return false
}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	if isDoubleNegative(sentence) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}
```

