```powershell
# Get the domain name
$domain = (Get-ADDomain).Name

# Function to check if an SID exists only in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $users = Get-ADUser -Filter {SID -eq $sid} -Properties MemberOf
    $groups = Get-ADGroup -Filter {SID -eq $sid} -Properties MemberOf

    foreach ($user in $users) {
        if ($user.MemberOf -contains "$domain\$($user.SamAccountName)") {
            return $true
        }
    }

    foreach ($group in $groups) {
        if ($group.MemberOf -contains "$domain\$($group.SamAccountName)") {
            return $true
        }
    }

    return $false
}

# Recursive function to check ACLs for folders and subfolders
function CheckACLsForFolders($folderPath) {
    Get-Acl -Path $folderPath | ForEach-Object {
        $acl = $_.Access

        foreach ($access in $acl) {
            if ($access.IdentityReference -match '^S-1-5-21-') {
                $sid = New-Object System.Security.Principal.SecurityIdentifier($access.IdentityReference)
                if (CheckSIDInSIDHistory($sid.Value)) {
                    Write-Host "The ACL for $folderPath contains a reference to an SID that exists only in the SIDHistory of a user or group in the domain."
                }
            }
        }
    }

    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        CheckACLsForFolders($_.FullName)
    }
}

# Start the recursive check
CheckACLsForFolders("C:\Your_Starting_Folder")
```

Replace `"C:\Your_Starting_Folder"` with the starting folder you want to check. This script will recursively check all folders and subfolders in the specified starting folder and its descendants.
